/**
 * Adaptive Report Consistency Tests
 *
 * Locks in the contract between the persistence path and the reconstruction
 * path: a report generated from a persisted `_adaptive` blob MUST be band-
 * and count-equivalent to one generated by reconstruction from declared
 * organization form. Version drift MUST trigger deterministic re-routing.
 */

import { describe, expect, it } from 'vitest';

import {
  buildPersistedAdaptiveContext,
  embedPersistedAdaptiveContext,
  extractPersistedAdaptiveContext,
  PERSISTED_ADAPTIVE_KEY,
} from '../adaptation/persistedAdaptiveContext';
import { resolveAdaptiveContext } from '../adaptation/reconstructAdaptiveContext';
import { classifyOrgContext } from '../adaptation/orgContextClassifier';
import { routeQuestionBank } from '../adaptation/questionRoutingEngine';
import { ROUTING_ENGINE_VERSION } from '../adaptation/routingTypes';
import type { RoutableQuestion } from '../adaptation/routingTypes';
import { ALL_QUESTIONS, QUESTION_BANK_VERSION } from '../questions';

const BANK = ALL_QUESTIONS as any as RoutableQuestion[];

const RAW_FORM_FEDERATION: Record<string, string> = {
  ctx_org_type: 'federation',
  ctx_sector: 'labour_union',
  ctx_membership_size: '50000_plus',
  ctx_years_operating: '30_plus_years',
  ctx_respondent_role: 'self_board_member',
};

const RAW_FORM_SMALL: Record<string, string> = {
  ctx_org_type: 'local_union',
  ctx_sector: 'labour_union',
  ctx_membership_size: 'under_100',
  ctx_years_operating: '15_to_29_years',
  ctx_respondent_role: 'self_senior_leader',
};

describe('Adaptive Report Consistency', () => {
  it('persisted blob equals deterministic build for the same form', () => {
    const profile = classifyOrgContext({ rawForm: RAW_FORM_FEDERATION });
    const bank = routeQuestionBank(BANK, profile);
    const a = buildPersistedAdaptiveContext(profile, bank, QUESTION_BANK_VERSION);
    const b = buildPersistedAdaptiveContext(profile, bank, QUESTION_BANK_VERSION);
    expect(a).toEqual(b);
  });

  it('resolveAdaptiveContext returns "persisted" when versions match', () => {
    const profile = classifyOrgContext({ rawForm: RAW_FORM_FEDERATION });
    const bank = routeQuestionBank(BANK, profile);
    const adaptive = buildPersistedAdaptiveContext(profile, bank, QUESTION_BANK_VERSION);
    const orgContext = embedPersistedAdaptiveContext(RAW_FORM_FEDERATION, adaptive);

    const resolution = resolveAdaptiveContext({
      organizationContext: orgContext,
      questionBank: BANK,
      currentQuestionBankVersion: QUESTION_BANK_VERSION,
    });

    expect(resolution.source).toBe('persisted');
    expect(resolution.fallbackUsed).toBe(false);
    expect(resolution.compatibilityWarnings).toEqual([]);
    expect(resolution.adaptiveContext.profileBands).toEqual(adaptive.profileBands);
    expect(resolution.adaptiveContext.includedQuestionIds).toEqual(
      adaptive.includedQuestionIds,
    );
  });

  it('resolveAdaptiveContext reroutes when no persisted blob is present', () => {
    const resolution = resolveAdaptiveContext({
      organizationContext: RAW_FORM_SMALL,
      questionBank: BANK,
      currentQuestionBankVersion: QUESTION_BANK_VERSION,
    });

    expect(resolution.source).toBe('rerouted');
    // Rerouted output must equal a direct deterministic build.
    const profile = classifyOrgContext({ rawForm: RAW_FORM_SMALL });
    const bank = routeQuestionBank(BANK, profile);
    const direct = buildPersistedAdaptiveContext(profile, bank, QUESTION_BANK_VERSION);
    expect(resolution.adaptiveContext.profileBands).toEqual(direct.profileBands);
    expect(resolution.adaptiveContext.includedQuestionIds).toEqual(
      direct.includedQuestionIds,
    );
  });

  it('resolveAdaptiveContext reconstructs on questionBankVersion drift', () => {
    const profile = classifyOrgContext({ rawForm: RAW_FORM_FEDERATION });
    const bank = routeQuestionBank(BANK, profile);
    const stalePersisted = buildPersistedAdaptiveContext(
      profile,
      bank,
      QUESTION_BANK_VERSION - 1,
    );
    const orgContext = embedPersistedAdaptiveContext(RAW_FORM_FEDERATION, stalePersisted);

    const resolution = resolveAdaptiveContext({
      organizationContext: orgContext,
      questionBank: BANK,
      currentQuestionBankVersion: QUESTION_BANK_VERSION,
    });

    expect(resolution.source).toBe('reconstructed');
    expect(resolution.adaptiveContext.questionBankVersion).toBe(QUESTION_BANK_VERSION);
    expect(resolution.compatibilityWarnings.length).toBeGreaterThan(0);
  });

  it('resolveAdaptiveContext returns safe_default when no context is available', () => {
    const resolution = resolveAdaptiveContext({
      organizationContext: null,
      questionBank: BANK,
      currentQuestionBankVersion: QUESTION_BANK_VERSION,
    });

    expect(resolution.source).toBe('safe_default');
    expect(resolution.fallbackUsed).toBe(true);
  });

  it('persisted shape extraction validates structure', () => {
    const valid = embedPersistedAdaptiveContext(
      {},
      buildPersistedAdaptiveContext(
        classifyOrgContext({ rawForm: RAW_FORM_SMALL }),
        routeQuestionBank(BANK, classifyOrgContext({ rawForm: RAW_FORM_SMALL })),
        QUESTION_BANK_VERSION,
      ),
    );
    expect(extractPersistedAdaptiveContext(valid)).not.toBeNull();
    expect(extractPersistedAdaptiveContext({ [PERSISTED_ADAPTIVE_KEY]: { bogus: true } })).toBeNull();
    expect(extractPersistedAdaptiveContext(null)).toBeNull();
    expect(extractPersistedAdaptiveContext(undefined)).toBeNull();
  });

  it('persisted blob routeVersion matches current engine', () => {
    const profile = classifyOrgContext({ rawForm: RAW_FORM_FEDERATION });
    const bank = routeQuestionBank(BANK, profile);
    const persisted = buildPersistedAdaptiveContext(profile, bank, QUESTION_BANK_VERSION);
    expect(persisted.routeVersion).toBe(ROUTING_ENGINE_VERSION);
  });
});
